const uniqueIds=(ids:string[])=>[...new Set(ids)];
const projectDataCenter=(dc:DataCenter,registeredIds:Set<string>):SharedFabricProjection=>{
  const spineIds=uniqueIds(dc.pods.flatMap(pod=>pod.spineIds));
  const leafIds=uniqueIds(dc.pods.flatMap(pod=>pod.domains.flatMap(domain=>domain.leafIds)));
  const memberToPlannedId=new Map<string,string>([
    ...spineIds.map((id,index)=>[id,plannedNodeId('Spine',index)] as const),
    ...leafIds.map((id,index)=>[id,plannedNodeId('Leaf',index)] as const),
  ]);
  const assignments:DeviceAssignments={};
  memberToPlannedId.forEach((plannedId,deviceId)=>{if(registeredIds.has(deviceId))assignments[plannedId]=deviceId});
  const expectedPairs=new Set<string>();
  dc.pods.forEach(pod=>pod.domains.forEach(domain=>domain.leafIds.forEach(leafId=>pod.spineIds.forEach(spineId=>expectedPairs.add(pairKey(leafId,spineId))))));
  const links=[...expectedPairs].flatMap((pair,index)=>{
    const [sourceDeviceId,targetDeviceId]=pair.split('::');
    const source=memberToPlannedId.get(sourceDeviceId);const target=memberToPlannedId.get(targetDeviceId);
    return source&&target?[{id:`REL-SHARED-${dc.id}-${index}`,source,target,state:'design' as const,relationship:'planned' as const}]:[];
  });
  return{spineIds,leafIds,memberIds:[...spineIds,...leafIds],memberToPlannedId,assignments,links,expectedPairs};
};
const sharedFabricDesign=(dc:DataCenter,state:AIDCFabricState,inventory:InventoryTopologyState,previous?:FabricDesign):FabricDesign=>{
  const registeredIds=new Set(inventory.registered.map(device=>device.id));
  const projection=projectDataCenter(dc,registeredIds);
  const mapped=projection.memberIds.filter(id=>registeredIds.has(id)).length;
  const observed=inventory.connections.filter(link=>projection.expectedPairs.has(pairKey(link.source,link.target))).length;
  const topology=[`${dc.pods.length} Pod`,`${projection.spineIds.length} Spine`,`${projection.leafIds.length} Leaf`].join(' · ');
  const baselineName=dc.id===AIDC_FABRIC_01.dcId&&dc.name===AIDC_FABRIC_01.dcName?AIDC_FABRIC_01.name:dc.name;
  const leafDeploymentModel:LeafDeploymentModel=previous?.leafDeploymentModel||(dc.pods.some(pod=>pod.domains.some(domain=>domain.mlag))?'mlag':'standalone');
  return{id:fabricIdForDataCenter(dc.id),name:baselineName,description:previous?.description||'L3 leaf-spine Fabric managed by the shared Studio and Inventory data model.',useCase:'aidc',designApproach:previous?.designApproach||'validated',leafDeploymentModel,referenceDesign:'Standard AI Leaf-Spine',type:'AIDC Leaf-Spine',topology,pods:dc.pods.length,spines:projection.spineIds.length,leafs:projection.leafIds.length,borders:0,devices:projection.memberIds.length,alignment:`${mapped}/${projection.memberIds.length} mapped · ${observed}/${projection.expectedPairs.size} LLDP`,deploymentStatus:'Pending Changes',lastModified:`${state.updatedAt.includes('T')?'Just now':state.updatedAt} · L3 Leaf-Spine Fabric`,revision:state.revision,workspaceId:previous?.workspaceId||(dc.id===AIDC_FABRIC_01.dcId?AIDC_FABRIC_01.workspaceId:''),sharedDataCenterId:dc.id};
};

