const ContributionImpactComparison = ({sourceName,devices}:{sourceName:string;devices:ConfigPreviewDevice[]}) => {
  const impactedDevices=devices.filter(device=>device.lines.some(line=>line.source===sourceName));
  const [deviceId,setDeviceId]=useState(impactedDevices[0]?.id||'');
  const [changesOnly,setChangesOnly]=useState(false);
  const device=impactedDevices.find(item=>item.id===deviceId)||impactedDevices[0];
  const lines=device?.lines.filter(line=>line.source===sourceName&&(!changesOnly||line.state!=='same'))||[];
  const otherSources=device?.sources.filter(source=>source!==sourceName)||[];
  if(!device)return <div className="grid min-h-0 flex-1 place-items-center p-8 text-[9px] text-slate-400">This source does not currently generate device configuration.</div>;
  return <div className="min-h-0 flex-1 overflow-auto p-3 sm:p-5"><div className="flex flex-wrap items-center gap-3 rounded-lg border border-slate-200 bg-slate-50/70 px-4 py-3"><label className="flex min-w-[220px] flex-1 flex-wrap items-center gap-2 text-[8px] font-medium text-slate-500"><Server size={11}/>Target device<select value={device.id} onChange={event=>setDeviceId(event.target.value)} className="w-full min-w-[180px] rounded border border-slate-300 bg-white px-2.5 py-2 text-[9px] text-slate-700 sm:w-64">{impactedDevices.map(item=><option key={item.id} value={item.id}>{item.hostname} · {item.plannedNode}</option>)}</select></label><span className="min-w-0 flex-1 truncate text-[8px] text-slate-400" title={otherSources.join(' · ')}>{otherSources.length?`Other active sources on this device: ${otherSources.join(' · ')}`:'No other active configuration sources on this device'}</span><label className="flex items-center gap-2 whitespace-nowrap text-[8px] text-slate-500"><input type="checkbox" checked={changesOnly} onChange={event=>setChangesOnly(event.target.checked)} className="accent-blue-600"/>Changed lines only</label></div><div className="mt-4 grid min-w-[680px] grid-cols-[minmax(0,1fr)_150px_minmax(0,1fr)] border border-slate-200 bg-slate-50 px-3 py-2.5 text-[8px] font-semibold text-slate-600"><span>Designed Contribution</span><span className="text-center">Change / Source</span><span>Running Configuration</span></div><div className="min-w-[680px] border-x border-b border-slate-200">{lines.map(line=><div key={line.id} className="grid grid-cols-[minmax(0,1fr)_150px_minmax(0,1fr)] border-b border-slate-100 last:border-b-0"><code className={`min-h-10 whitespace-pre-wrap px-3 py-2.5 text-[9px] ${line.state==='added'?'bg-emerald-50 text-emerald-800':line.state==='modified'?'bg-amber-50 text-amber-800':line.state==='removed'?'bg-slate-50 text-slate-400':'bg-white text-slate-700'}`}>{line.designed||'—'}</code><span className="flex flex-col items-center justify-center border-x border-slate-100 px-2 py-2 text-center"><b className={`text-[8px] ${line.state==='added'?'text-emerald-700':line.state==='modified'?'text-amber-700':line.state==='removed'?'text-red-700':'text-slate-400'}`}>{line.state==='same'?'Aligned':line.state[0].toUpperCase()+line.state.slice(1)}</b><span className="mt-0.5 text-[7px] leading-3 text-slate-400">{sourceName}</span></span><code className={`min-h-10 whitespace-pre-wrap px-3 py-2.5 text-[9px] ${line.state==='removed'?'bg-red-50 text-red-800':line.state==='modified'?'bg-amber-50 text-amber-800':'bg-white text-slate-700'}`}>{line.running||'—'}</code></div>)}{!lines.length&&<div className="py-12 text-center text-[9px] text-slate-400">No contribution lines match the current filter.</div>}</div></div>;
};
