    {reviewedContribution&&<div className="fixed inset-0 z-[145] flex items-center justify-center bg-slate-900/40 p-3 sm:p-6"><div className="flex max-h-[92vh] w-[min(1180px,96vw)] flex-col overflow-hidden rounded-lg border border-slate-200 bg-white shadow-2xl"><header className="flex flex-shrink-0 items-start justify-between border-b border-slate-200 px-5 py-4"><div><div className="flex flex-wrap items-center gap-2"><h2 className="text-[13px] font-semibold text-slate-900">Configuration Impact · {reviewedContribution.name}</h2>{reviewedContributionSummary&&<span className={`flex items-center gap-1.5 text-[8px] font-semibold ${reviewedContributionSummary.stateMeta.text}`}><i className={`h-2 w-2 rounded-full ${reviewedContributionSummary.stateMeta.dot}`}/>{reviewedContributionSummary.state}</span>}</div><p className="mt-1 text-[8px] text-slate-500">Compare this source's Designed Contribution with the current Running Configuration on each target device.</p></div><button onClick={()=>setContributionReviewId(undefined)} className="text-slate-400 hover:text-slate-700"><X size={16}/></button></header><div className="grid flex-shrink-0 grid-cols-3 border-b border-slate-200 bg-slate-50/70"><div className="border-r border-slate-200 px-5 py-3"><span className="text-[8px] text-slate-400">Effective Scope</span><b className="mt-1 block truncate text-[9px] text-slate-700" title={reviewedContribution.effectiveScope}>{reviewedContribution.effectiveScope}</b></div><div className="border-r border-slate-200 px-5 py-3"><span className="text-[8px] text-slate-400">Target Devices</span><b className="mt-1 block text-[11px] text-slate-700">{reviewedContributionSummary?.deviceCount||0}</b></div><div className="px-5 py-3"><span className="text-[8px] text-slate-400">Changed Lines</span><b className={`mt-1 block text-[11px] ${reviewedContributionSummary?.changedLines?'text-amber-700':'text-emerald-700'}`}>{reviewedContributionSummary?.changedLines||0}</b></div></div><ContributionImpactComparison key={reviewedContribution.id} sourceName={reviewedContribution.name} devices={configurationPreviewDevices}/><footer className="flex flex-shrink-0 justify-end gap-2 border-t border-slate-200 bg-slate-50/70 px-5 py-3"><div className="flex gap-2"><button onClick={()=>setContributionReviewId(undefined)} className="rounded-md border border-slate-300 bg-white px-4 py-2 text-[9px] font-semibold text-slate-600">Close</button><button onClick={()=>{setContributionReviewId(undefined);affectedStudios.some(item=>item.id===reviewedContribution.id)?openScopeRemovalReview(reviewedContribution.id):setOpenedStudioId(reviewedContribution.id)}} className="rounded-md bg-blue-600 px-4 py-2 text-[9px] font-semibold text-white">{affectedStudios.some(item=>item.id===reviewedContribution.id)?'Review Scope Removal':'Open Studio'}</button></div></footer></div></div>}
    {previewDevice&&<div className="fixed inset-0 z-[140] flex items-center justify-center bg-slate-900/40 p-3 sm:p-6"><div className="flex max-h-[92vh] w-[min(1180px,96vw)] flex-col overflow-hidden rounded-lg border border-slate-200 bg-white shadow-2xl"><header className="flex flex-shrink-0 items-start justify-between border-b border-slate-200 px-5 py-4"><div><h2 className="text-[13px] font-semibold text-slate-900">Review Change · {previewDevice.hostname}</h2><p className="mt-1 text-[8px] text-slate-500">Configuration Preview · {previewDevice.plannedNode} · {previewDevice.model}</p></div><button onClick={()=>setPreviewDeviceId(undefined)} className="text-slate-400 hover:text-slate-700"><X size={16}/></button></header><div className="flex flex-shrink-0 flex-wrap items-center gap-3 border-b border-slate-200 bg-slate-50/70 px-5 py-3"><label className="flex min-w-[220px] flex-1 flex-wrap items-center gap-2 text-[8px] font-medium text-slate-500"><Search size={11}/>Device<select value={previewDevice.id} onChange={event=>setPreviewDeviceId(event.target.value)} className="w-full min-w-[180px] rounded border border-slate-300 bg-white px-2.5 py-2 text-[9px] text-slate-700 sm:w-64">{configurationPreviewDevices.map(device=><option key={device.id} value={device.id}>{device.hostname}</option>)}</select></label><label className="flex items-center gap-2 whitespace-nowrap text-[8px] text-slate-500"><input type="checkbox" checked={previewLineChangesOnly} onChange={event=>setPreviewLineChangesOnly(event.target.checked)} className="accent-blue-600"/>Changed lines only</label></div><div className="min-h-0 flex-1 overflow-auto p-5"><div className="grid min-w-[680px] grid-cols-[minmax(0,1fr)_150px_minmax(0,1fr)] border border-slate-200 bg-slate-50 px-3 py-2.5 text-[8px] font-semibold text-slate-600"><span>Designed Configuration</span><span className="text-center">Change / Source</span><span>Running Configuration</span></div><div className="min-w-[680px] border-x border-b border-slate-200">{previewDevice.lines.filter(line=>!previewLineChangesOnly||line.state!=='same').map(line=><div key={line.id} className="grid grid-cols-[minmax(0,1fr)_150px_minmax(0,1fr)] border-b border-slate-100 last:border-b-0"><code className={`min-h-9 whitespace-pre-wrap px-3 py-2.5 text-[9px] ${line.state==='added'?'bg-emerald-50 text-emerald-800':line.state==='modified'?'bg-amber-50 text-amber-800':line.state==='removed'?'bg-slate-50 text-slate-400':'bg-white text-slate-700'}`}>{line.designed||'—'}</code><span className="flex flex-col items-center justify-center border-x border-slate-100 px-2 py-2 text-center"><b className={`text-[8px] ${line.state==='added'?'text-emerald-700':line.state==='modified'?'text-amber-700':line.state==='removed'?'text-red-700':'text-slate-400'}`}>{line.state==='same'?'Unchanged':line.state[0].toUpperCase()+line.state.slice(1)}</b><span className="mt-0.5 text-[7px] leading-3 text-slate-400">{line.source}</span></span><code className={`min-h-9 whitespace-pre-wrap px-3 py-2.5 text-[9px] ${line.state==='removed'?'bg-red-50 text-red-800':line.state==='modified'?'bg-amber-50 text-amber-800':'bg-white text-slate-700'}`}>{line.running||'—'}</code></div>)}{previewDevice.lines.filter(line=>!previewLineChangesOnly||line.state!=='same').length===0&&<div className="py-12 text-center text-[9px] text-slate-400">No changed configuration lines for this device.</div>}</div></div><footer className="flex flex-shrink-0 flex-wrap items-center justify-between gap-2 border-t border-slate-200 bg-slate-50/70 px-5 py-3"><span className="min-w-[160px] flex-1 text-[8px] text-slate-500">Preview output is read-only.</span><button onClick={()=>setPreviewDeviceId(undefined)} className="rounded-md bg-blue-600 px-4 py-2 text-[9px] font-semibold text-white">Close</button></footer></div></div>}
    {scopeRemovalReviewOpen&&<div className="fixed inset-0 z-[150] flex items-center justify-center bg-slate-950/50 p-4 sm:p-6"><div className="flex max-h-[92vh] w-[min(900px,96vw)] flex-col overflow-hidden rounded-xl border-2 border-red-400 bg-white shadow-2xl"><header className="flex items-start justify-between border-b border-red-200 bg-red-50 px-5 py-4"><div><h2 className="flex items-center gap-2 text-[14px] font-extrabold text-red-900"><AlertTriangle size={17}/>Confirm Studio Assignment Removals</h2><p className="mt-1 text-[9px] text-red-700">This records candidate approval only. It does not modify Studio mainline, shared Fabric membership, Registered Devices, or Running Configuration.</p></div><button type="button" onClick={()=>setScopeRemovalReviewOpen(false)} className="rounded p-1 text-red-500 hover:bg-red-100"><X size={17}/></button></header><div className="min-h-0 flex-1 overflow-auto p-5"><section className="rounded-lg border-2 border-red-300 bg-red-50 p-4"><h3 className="text-[10px] font-extrabold text-red-900">Objects scheduled for removal</h3><div className="mt-2 grid grid-cols-2 gap-2">{plannedRemovalDevices.map(({device,role,plannedNode})=><div key={device.id} className="rounded-md border border-red-200 bg-white p-3 text-[8px]"><b className="block text-[9px] text-red-900">{device.hostname}</b><span className="mt-1 block font-mono text-red-700">Device ID: {device.id}</span><span className="mt-1 block text-red-700">Role: {device.customRole||role}</span><span className="mt-1 block text-red-700">Planned Node: {plannedNode}</span></div>)}</div><div className="mt-3 grid grid-cols-4 overflow-hidden rounded-md border border-red-200 bg-white text-[8px]"><span className="border-r border-red-100 p-2"><i className="block not-italic text-red-500">Removed devices</i><b>{plannedRemovalDevices.length}</b></span><span className="border-r border-red-100 p-2"><i className="block not-italic text-red-500">Interfaces</i><b>{removedInterfaceCount}</b></span><span className="border-r border-red-100 p-2"><i className="block not-italic text-red-500">Relationships</i><b>{removedRelationshipCount}</b></span><span className="p-2"><i className="block not-italic text-red-500">Affected Studios</i><b>{affectedStudios.length}</b></span></div></section><h3 className="mt-5 text-[10px] font-bold text-slate-800">Confirm each independent Studio Assignment owner</h3><div className="mt-2 space-y-2">{affectedStudios.map(studio=>{const impact=studioScopeImpact(studio);const checked=scopeRemovalDraftStudioIds.has(studio.id);return <label key={studio.id} className={`block rounded-lg border-2 p-3 ${checked?'border-red-400 bg-red-50':'border-slate-200 bg-white'}`}><div className="flex items-start gap-3"><input type="checkbox" checked={checked} onChange={()=>setScopeRemovalDraftStudioIds(current=>{const next=new Set(current);next.has(studio.id)?next.delete(studio.id):next.add(studio.id);return next})} className="mt-0.5 h-4 w-4 accent-red-700"/><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-2"><b className="text-[10px] text-slate-900">{studio.name}</b><Pill tone={scopeRemovalConfirmed(studio)?'green':'red'}>{scopeRemovalConfirmed(studio)?'Previously confirmed':'Confirmation required'}</Pill></span><span className="mt-2 grid grid-cols-2 overflow-hidden rounded border border-slate-200 bg-white text-[8px]"><span className="border-r border-slate-100 p-2"><i className="block not-italic text-slate-400">Current Scope</i><b>{impact.currentScope} devices</b></span><span className="p-2"><i className="block not-italic text-red-500">Proposed Scope</i><b className="text-red-800">{impact.proposedScope} devices</b></span></span><span className="mt-2 block text-[8px] text-red-800"><b>Removed:</b> {impact.removedObjects.map(item=>`${item.device.hostname} · ${item.device.id} · ${item.plannedNode}`).join(' | ')}</span><span className="mt-1 block text-[8px] text-red-800"><b>Configuration contribution impact:</b> {impact.contributionImpact}</span></span></div></label>})}</div><label className="mt-5 flex items-start gap-3 rounded-lg border-2 border-red-300 bg-red-50 p-4 text-[9px] font-bold leading-5 text-red-900"><input type="checkbox" checked={scopeRemovalAcknowledged} onChange={event=>setScopeRemovalAcknowledged(event.target.checked)} className="mt-0.5 h-4 w-4 accent-red-700"/><span>I understand that the checked Studios will stop generating configuration for the selected deployed devices after the candidate changes pass Workspace Build, Submit, Tasks, and Change Control.</span></label></div><footer className="flex items-center justify-between gap-3 border-t border-red-200 bg-red-50 px-5 py-4"><span className="text-[8px] font-semibold text-red-800">{scopeRemovalDraftStudioIds.size}/{affectedStudios.length} Studio confirmations selected</span><div className="flex gap-2"><button type="button" onClick={()=>setScopeRemovalReviewOpen(false)} className="rounded-md border border-slate-300 bg-white px-4 py-2 text-[9px] font-semibold text-slate-600">Cancel</button><button type="button" disabled={!scopeRemovalAcknowledged||scopeRemovalDraftStudioIds.size===0} onClick={confirmScopeRemoval} className="rounded-md bg-red-700 px-4 py-2 text-[9px] font-extrabold text-white hover:bg-red-800 disabled:cursor-not-allowed disabled:opacity-40">Confirm Assignment Removals</button></div></footer></div></div>}
    {deviceEditorOpen&&<div className="fixed inset-0 z-[130] flex items-center justify-center bg-slate-900/35 p-6"><div className="w-[480px] rounded-xl border border-slate-200 bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-slate-200 px-5 py-4"><div><h2 className="text-[13px] font-semibold text-slate-900">Add Planned Device</h2></div><button onClick={()=>setDeviceEditorOpen(false)} className="text-slate-400"><X size={16}/></button></div><div className="space-y-4 p-5"><Field label="Planned device name"><input autoFocus value={deviceDraft.name} onChange={event=>setDeviceDraft(current=>({...current,name:event.target.value}))} placeholder="Service-Leaf-01" className="w-full rounded-md border bg-white px-3 py-2 text-[10px]"/>{deviceNameDuplicate&&<span className="mt-1 block text-[8px] text-red-700">A planned node already uses this name.</span>}</Field><Field label="Design role"><Select value={deviceDraft.role} onChange={value=>setDeviceDraft(current=>({...current,role:value as DeviceDraft['role']}))}>{customTemplate.roles.map(item=><option key={item.role} value={item.role}>{item.label}</option>)}</Select></Field></div><div className="flex justify-end gap-2 border-t border-slate-200 px-5 py-3"><button onClick={()=>setDeviceEditorOpen(false)} className="border border-slate-300 px-3 py-2 text-[9px] text-slate-600">Cancel</button><button disabled={!deviceDraft.name.trim()||deviceNameDuplicate} onClick={addManualDevice} className="bg-blue-600 px-3 py-2 text-[9px] font-semibold text-white disabled:opacity-40">Add Planned Device</button></div></div></div>}
    {linkEditorOpen&&<div className="fixed inset-0 z-[130] flex items-center justify-center bg-slate-900/35 p-6"><div className="w-[560px] rounded-xl border border-slate-200 bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-slate-200 px-5 py-4"><div><h2 className="text-[13px] font-semibold text-slate-900">Add Expected Relationship</h2><p className="mt-1 text-[8px] text-slate-500">Defines logical adjacency only. Physical interfaces and LLDP are matched during Reconcile.</p></div><button onClick={()=>setLinkEditorOpen(false)} className="text-slate-400"><X size={16}/></button></div><div className="grid grid-cols-2 gap-3 p-5"><Field label="Source planned node"><Select value={linkDraft.source} onChange={value=>setLinkDraft(current=>({...current,source:value}))}><option value="">Select source</option>{designNodes.map(node=><option key={node.id} value={node.id}>{node.label}</option>)}</Select></Field><Field label="Target planned node"><Select value={linkDraft.target} onChange={value=>setLinkDraft(current=>({...current,target:value}))}><option value="">Select target</option>{designNodes.filter(node=>node.id!==linkDraft.source).map(node=><option key={node.id} value={node.id}>{node.label}</option>)}</Select></Field></div>{linkEndpointDuplicate&&<div className="mx-5 mb-4 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-[8px] text-red-700">This logical relationship already exists in the design.</div>}<div className="flex justify-end gap-2 border-t border-slate-200 px-5 py-3"><button onClick={()=>setLinkEditorOpen(false)} className="border border-slate-300 px-3 py-2 text-[9px] text-slate-600">Cancel</button><button disabled={!linkDraft.source||!linkDraft.target||linkDraft.source===linkDraft.target||linkEndpointDuplicate} onClick={addManualLink} className="bg-blue-600 px-3 py-2 text-[9px] font-semibold text-white disabled:opacity-40">Add Expected Relationship</button></div></div></div>}
